contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 newBetLimit, uint256 newDifficulty, uint256 wagerAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (wagerAmount)); require(wagerAmount <= 1000000000000000000000000000000);
        require(newBetLimit > 0);
        require(newDifficulty > 0);
        require(newBetLimit == wagerAmount);
        require(address(this).balance >= wagerAmount);

        c.OpenToThePublic(); if (__ESBMC_reverted()) return;
        c.AdjustBetAmounts(newBetLimit); if (__ESBMC_reverted()) return;
        c.AdjustDifficulty(newDifficulty); if (__ESBMC_reverted()) return;

        uint256 recordedBetLimit = c.currentBetLimit(); if (__ESBMC_reverted()) return;
        uint256 recordedDifficulty = c.currentDifficulty(); if (__ESBMC_reverted()) return;
        uint256 balanceBeforeWager = address(c).balance;

        c.wager{value: wagerAmount}(); if (__ESBMC_reverted()) return;

        uint256 balanceAfterWager = address(c).balance;
        bool playerHasWagered = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        assert(recordedBetLimit == newBetLimit &&
            recordedDifficulty == newDifficulty &&
            playerHasWagered &&
            balanceAfterWager == balanceBeforeWager + wagerAmount);
    }

    receive() external payable {}
}

