pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 newBetLimit, uint256 newDifficulty, uint256 wagerAmount) internal {
        wagerAmount = bound(wagerAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(newBetLimit > 0);
        vm.assume(newDifficulty > 0);
        newBetLimit = wagerAmount;
        vm.assume(address(this).balance >= wagerAmount);
        try c.OpenToThePublic() {} catch { return; }
        try c.AdjustBetAmounts(newBetLimit) {} catch { return; }
        try c.AdjustDifficulty(newDifficulty) {} catch { return; }
        uint256 recordedBetLimit;
        try c.currentBetLimit() returns (uint256 __r) { recordedBetLimit = __r; } catch { return; }
        uint256 recordedDifficulty;
        try c.currentDifficulty() returns (uint256 __r) { recordedDifficulty = __r; } catch { return; }
        uint256 balanceBeforeWager = address(c).balance;
        try c.wager{value: wagerAmount}() {} catch { return; }
        uint256 balanceAfterWager = address(c).balance;
        bool playerHasWagered;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { playerHasWagered = __r; } catch { return; }
        assertTrue(recordedBetLimit == newBetLimit &&
            recordedDifficulty == newDifficulty &&
            playerHasWagered &&
            balanceAfterWager == balanceBeforeWager + wagerAmount);
    }

    function testFuzz_run(uint256 newBetLimit, uint256 newDifficulty, uint256 wagerAmount) public {
        _run(newBetLimit, newDifficulty, wagerAmount);
    }

    receive() external payable {}
}
